import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  stripAngleBracketText,
  redactJwtLikeTokens,
  redactKnownSecrets,
  sanitizeBoundedText,
  sanitizeErrorMessage,
} from '../../packages/notification-contract/src/index.js';
import {
  encodeCcv2PathSegment,
  Ccv2TransportError,
  redactTransportText,
} from '../../packages/ccv2-client/src/index.js';

// Frozen outputs from the current Actions, not expectations generated by the new APIs.
// Source SHAs and capture method are recorded in docs/remaining-extraction-audit.md.
const fixtures: {
  text: { value: string; secrets: string[]; max: number; build: string; deploy: string }[];
  paths: {
    value: string;
    build: { accepted: boolean; encoded?: string };
    deploy: { accepted: boolean; encoded?: string };
  }[];
} = JSON.parse(readFileSync('compatibility/fixtures/remaining-primitives.json', 'utf8'));

describe('Build/Deploy sanitization composition compatibility', () => {
  fixtures.text.forEach((fixture, index) => {
    it(`preserves both consumer outputs for captured text case ${index}`, () => {
      const { value, secrets, max } = fixture;
      const buildText = redactJwtLikeTokens(stripAngleBracketText(redactKnownSecrets(value, secrets)));
      const build = buildText.trim()
        ? sanitizeBoundedText(
            sanitizeErrorMessage(redactTransportText(buildText, secrets), secrets),
            max,
          ).trim()
        : '';
      const deployText = redactJwtLikeTokens(stripAngleBracketText(redactTransportText(value, secrets)));
      const deploy = deployText.trim()
        ? sanitizeBoundedText(sanitizeErrorMessage(deployText, secrets), max).trim()
        : '';
      expect(build).toBe(fixture.build);
      expect(deploy).toBe(fixture.deploy);
    });
  });
  it('keeps provider escaping, bounds and other sanitization opt-in', () => {
    expect(stripAngleBracketText('a<unclosed')).toBe('a');
    expect(stripAngleBracketText('a<<b>c>d')).toBe('acd');
    expect(stripAngleBracketText('<script>alert(1)</script>')).toBe('alert(1)');
    expect(stripAngleBracketText('&lt;b&gt; @here')).toBe('&lt;b&gt; @here');
    expect(stripAngleBracketText('')).toBe('');
    expect(stripAngleBracketText('x'.repeat(1001))).toHaveLength(1001);
    expect(redactJwtLikeTokens('eyJheader.payload.signature eyJother.second.third')).toBe(
      '[REDACTED] [REDACTED]',
    );
    expect(redactJwtLikeTokens('eyJ.a.b not.a.token')).toBe('eyJ.a.b not.a.token');
    expect(redactJwtLikeTokens('')).toBe('');
  });
});

describe('CCv2 path segment compatibility', () => {
  fixtures.paths.forEach((fixture, index) => {
    it(`preserves Build/Deploy acceptance and encoding for captured path case ${index}`, () => {
      expect(fixture.build).toEqual(fixture.deploy);
      if (fixture.build.accepted) {
        expect(encodeCcv2PathSegment(fixture.value)).toBe(fixture.build.encoded);
      } else {
        expect(() => encodeCcv2PathSegment(fixture.value)).toThrow(Ccv2TransportError);
        try {
          encodeCcv2PathSegment(fixture.value);
        } catch (error) {
          expect((error as Ccv2TransportError).toJSON()).toEqual({ code: 'INVALID_URL' });
          expect((error as Error).message).toBe('CCv2 transport: INVALID_URL.');
          expect((error as Error).stack).toBeUndefined();
        }
      }
    });
  });
});
